export class ContractError extends Error {}

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

export async function fetchInvoices(transport) {
  const items = await transport.get("/invoices");
  items.forEach((item, index) => {
    const invoice = item ?? {};
    if (typeof invoice.id !== "string") fail(index, "id");
    if (typeof invoice.number !== "string") fail(index, "number");
    if (typeof invoice.currency !== "string" || !CURRENCY_PATTERN.test(invoice.currency)) {
      fail(index, "currency");
    }
    if (!Number.isInteger(invoice.amountMinor)) fail(index, "amountMinor");
  });
  return items;
}

function fail(index, field) {
  throw new ContractError(`invoice at index ${index}: field "${field}" breaks the contract`);
}
